'use strict';
// One-time patch: Sound effects (made by code, or your own sound files) and Auto captions (mark speech, or listen with a speech model on this device).
// Run from the project folder:   node tools/apply-sound-captions.js
// It checks that every spot it needs to change is found exactly once BEFORE writing anything, so it does everything or nothing.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const B = {"sfxJs":"'use strict';\n/* Naki sound effects: a few effects made by code (no files to download), as mono sound at any sample rate, plus a WAV writer so an effect can be\n   kept like any other audio file and used by the preview and by both export engines. The same numbers always make the same sound. */\nvar NakiSfx = (function () {\n  var LIST = [\n    { key: 'whoosh', label: 'Whoosh', durMs: 700 }, { key: 'swipe', label: 'Swipe', durMs: 350 }, { key: 'pop', label: 'Pop', durMs: 220 },\n    { key: 'click', label: 'Click', durMs: 120 }, { key: 'ding', label: 'Ding', durMs: 1500 }, { key: 'coin', label: 'Coin', durMs: 650 },\n    { key: 'laser', label: 'Laser', durMs: 500 }, { key: 'boom', label: 'Boom', durMs: 1400 }, { key: 'riser', label: 'Riser', durMs: 2500 },\n    { key: 'drop', label: 'Drop', durMs: 900 }\n  ];\n  function find(key) { for (var i = 0; i < LIST.length; i++) if (LIST[i].key === key) return LIST[i]; return null; }\n  function rng(seed) { var s = seed >>> 0; return function () { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 2147483648 - 1; }; }\n  function lp(fc, sr) { return 1 - Math.exp(-2 * Math.PI * Math.max(20, fc) / sr); }   // one-pole low-pass coefficient\n  var TAU = 2 * Math.PI;\n\n  // Each effect fills out[i] from the time t (seconds) and the progress u (0 to 1). They keep their own little state (a filter, a phase).\n  var MAKERS = {\n    whoosh: function (sr, n, rnd) { var y = 0; return function (i, t, u) { var bell = Math.sin(Math.PI * u); y += lp(300 + 3700 * bell, sr) * (rnd() - y); return y * bell * bell * 2.2; }; },\n    swipe: function (sr, n, rnd) { var y = 0; return function (i, t, u) { var bell = Math.sin(Math.PI * u); y += lp(800 + 5200 * u, sr) * (rnd() - y); return y * bell * 2; }; },\n    pop: function (sr) { var ph = 0; return function (i, t) { ph += TAU * (250 + 650 * Math.exp(-t * 40)) / sr; return Math.sin(ph) * Math.exp(-t * 28); }; },\n    click: function (sr, n, rnd) { var y = 0; return function (i, t) { var x = rnd(); y += lp(3000, sr) * (x - y); return (x - y) * Math.exp(-t * 300); }; },\n    ding: function (sr) { return function (i, t) { return (Math.sin(TAU * 880 * t) * Math.exp(-t * 3) + 0.45 * Math.sin(TAU * 1320 * t) * Math.exp(-t * 4) + 0.2 * Math.sin(TAU * 2640 * t) * Math.exp(-t * 7)) * 0.7; }; },\n    coin: function (sr) { return function (i, t) { var f = t < 0.1 ? 988 : 1319, tt = t < 0.1 ? t : t - 0.1; return Math.sin(TAU * f * t) * Math.exp(-tt * (t < 0.1 ? 4 : 7)) * 0.8; }; },\n    laser: function (sr) { var ph = 0; return function (i, t, u) { ph += TAU * (2000 * Math.exp(-u * 2.3)) / sr; return Math.sin(ph) * (1 - u) * 0.8; }; },\n    boom: function (sr, n, rnd) { var ph = 0, y = 0; return function (i, t) { ph += TAU * (30 + 45 * Math.exp(-t * 5)) / sr; y += lp(400, sr) * (rnd() - y); return (Math.sin(ph) * Math.exp(-t * 2.8) + y * Math.exp(-t * 14) * 1.5) * 0.9; }; },\n    riser: function (sr, n, rnd) { var ph = 0, y = 0; return function (i, t, u) { ph += TAU * (200 + 1000 * u * u) / sr; y += lp(200 + 5800 * u, sr) * (rnd() - y); return (0.5 * Math.sin(ph) + y) * u * u; }; },\n    drop: function (sr) { var ph = 0; return function (i, t, u) { ph += TAU * (60 + 540 * Math.exp(-u * 4.5)) / sr; return Math.sin(ph) * (1 - u) * 0.9; }; }\n  };\n\n  // The effect as mono samples (Float32Array, loudest sample 0.85), or null for an unknown name.\n  function render(key, sr) {\n    var def = find(key); if (!def) return null;\n    sr = sr || 48000;\n    var n = Math.round(def.durMs * sr / 1000), out = new Float32Array(n), f = MAKERS[key](sr, n, rng(12345)), peak = 0, i;\n    for (i = 0; i < n; i++) { var v = f(i, i / sr, i / n); out[i] = v; if (Math.abs(v) > peak) peak = Math.abs(v); }\n    var k = peak > 0 ? 0.85 / peak : 0, rin = Math.max(1, Math.round(sr * 0.001)), rout = Math.max(1, Math.round(sr * 0.004));   // a 1 ms fade in and a 4 ms fade out, so it never clicks\n    for (i = 0; i < n; i++) { var g = Math.min(1, i / rin, (n - 1 - i) / rout); out[i] = out[i] * k * g; }\n    peak = 0; for (i = 0; i < n; i++) if (Math.abs(out[i]) > peak) peak = Math.abs(out[i]);\n    if (peak > 0) for (i = 0; i < n; i++) out[i] *= 0.85 / peak;   // the fades can only have lowered the loudest sample: bring it back to 0.85\n    return out;\n  }\n  // 16-bit mono WAV file bytes.\n  function toWav(samples, sr) {\n    sr = sr || 48000;\n    var n = samples.length, bytes = new Uint8Array(44 + n * 2), v = new DataView(bytes.buffer);\n    function str(o, s) { for (var i = 0; i < s.length; i++) bytes[o + i] = s.charCodeAt(i); }\n    str(0, 'RIFF'); v.setUint32(4, 36 + n * 2, true); str(8, 'WAVE'); str(12, 'fmt '); v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);\n    v.setUint32(24, sr, true); v.setUint32(28, sr * 2, true); v.setUint16(32, 2, true); v.setUint16(34, 16, true); str(36, 'data'); v.setUint32(40, n * 2, true);\n    for (var i = 0; i < n; i++) v.setInt16(44 + i * 2, Math.max(-32768, Math.min(32767, Math.round(samples[i] * 32767))), true);\n    return bytes;\n  }\n  var api = { LIST: LIST, find: find, render: render, toWav: toWav };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api;\n  if (typeof window !== 'undefined') { window.NakiSfx = api; window.NakiVersions = window.NakiVersions || {}; window.NakiVersions['sfx.js'] = 'sound'; }\n  return api;\n})();\n","captionsJs":"'use strict';\n/* Naki auto captions. Two helpers that work offline for any language, and one that listens:\n   - chunkRanges: turns the stretches where you were talking into caption slots (you type the words);\n   - segmentsFromChunks / splitLines: tidy what a speech model returns into caption lines;\n   - recognize: runs a Whisper speech model on THIS device (transformers.js, loaded from the internet the first time, and kept by the browser).\n   Whisper knows English well and some other languages; Luganda is not one of them, so check every line. */\nvar NakiCaptions = (function () {\n  var LIB_URL = 'https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.8.1/dist/transformers.min.js';\n  var MODELS = { english: { id: 'onnx-community/whisper-tiny.en', mb: 40 }, other: { id: 'onnx-community/whisper-base', mb: 90 } };\n  var LANGS = [\n    { key: 'english', label: 'English', model: 'english', lang: null },\n    { key: 'swahili', label: 'Swahili', model: 'other', lang: 'swahili' },\n    { key: 'auto', label: 'Other (detect)', model: 'other', lang: null }\n  ];\n  var loaded = {};\n\n  // [{ start, end }] stretches of speech: none longer than maxMs (a long one is cut into equal slots).\n  function chunkRanges(ranges, maxMs) {\n    var out = [];\n    (ranges || []).forEach(function (r) {\n      var len = r.end - r.start, k = Math.max(1, Math.ceil(len / maxMs)), step = len / k;\n      for (var i = 0; i < k; i++) out.push({ start: Math.round(r.start + i * step), end: Math.round(r.start + (i + 1) * step) });\n    });\n    return out;\n  }\n  // The model's chunks [{ timestamp: [startSec, endSec | null], text }] as [{ startMs, endMs, text }]; the last one has no end, so it runs to the end of the recording.\n  function segmentsFromChunks(chunks, totalMs) {\n    var out = [];\n    (chunks || []).forEach(function (c, i) {\n      var t = c.timestamp || [], s = t[0], e = t[1], nx = null;\n      if (s == null || isNaN(s)) return;\n      for (var j = i + 1; j < chunks.length && nx == null; j++) { var ns = chunks[j] && chunks[j].timestamp && chunks[j].timestamp[0]; if (ns != null && !isNaN(ns)) nx = ns; }\n      if (e == null || isNaN(e)) e = nx != null ? nx : (totalMs || 0) / 1000;\n      var text = String(c.text == null ? '' : c.text).replace(/\\s+/g, ' ').trim();\n      if (!text || /^[\\[(].*[\\])]$/.test(text)) return;   // \"[BLANK_AUDIO]\", \"(music)\"\n      var sm = Math.round(s * 1000), em = Math.max(Math.round(e * 1000), sm + 400);\n      out.push({ startMs: sm, endMs: totalMs ? Math.min(em, Math.max(totalMs, sm + 400)) : em, text: text });\n    });\n    return out;\n  }\n  // Long lines are broken at word boundaries into lines of at most maxChars, each getting time in proportion to its length.\n  function splitLines(segs, maxChars) {\n    var out = [];\n    (segs || []).forEach(function (sg) {\n      var words = sg.text.split(' '), lines = [], cur = '';\n      words.forEach(function (w) { if (cur && (cur + ' ' + w).length > maxChars) { lines.push(cur); cur = w; } else cur = cur ? cur + ' ' + w : w; });\n      if (cur) lines.push(cur);\n      var len = sg.endMs - sg.startMs, total = lines.join('').length || 1, at = sg.startMs, used = 0;\n      lines.forEach(function (l, i) {\n        used += l.length; var end = i === lines.length - 1 ? sg.endMs : sg.startMs + Math.round(len * used / total);\n        out.push({ startMs: at, endMs: end, text: l }); at = end;\n      });\n    });\n    return out;\n  }\n  // The voice recording as mono samples at 16000 Hz, which is what the model reads.\n  async function toMono16k(blob) {\n    var AC = (typeof OfflineAudioContext !== 'undefined') ? OfflineAudioContext : window.webkitOfflineAudioContext;\n    var ab = await new AC(1, 1, 16000).decodeAudioData(await blob.arrayBuffer());\n    var n = ab.length, ch = ab.numberOfChannels, out = new Float32Array(n);\n    for (var c = 0; c < ch; c++) { var d = ab.getChannelData(c); for (var i = 0; i < n; i++) out[i] += d[i] / ch; }\n    return { samples: out, durMs: Math.round(ab.duration * 1000) };\n  }\n  // opts: { language: 'english' | 'swahili' | 'auto', onStatus(text), lib / decode (for tests) }.  Resolves with [{ startMs, endMs, text }] in the time of the voice file.\n  async function recognize(blob, opts) {\n    opts = opts || {};\n    var say = opts.onStatus || function () {}, L = LANGS.filter(function (l) { return l.key === opts.language; })[0] || LANGS[0], M = MODELS[L.model];\n    say('Reading your voice recording...');\n    var audio = await (opts.decode || toMono16k)(blob);\n    say('Loading the speech model. The first time this downloads about ' + M.mb + ' MB, so it needs internet.');\n    var lib = opts.lib || await import(/* webpackIgnore: true */ LIB_URL);\n    if (!loaded[M.id]) {\n      loaded[M.id] = await lib.pipeline('automatic-speech-recognition', M.id, { progress_callback: function (p) {\n        if (p && p.status === 'progress' && typeof p.progress === 'number') say('Downloading the speech model... ' + Math.round(p.progress) + '%');\n      } });\n    }\n    say('Listening to your recording. This can take a few minutes.');\n    var o = { return_timestamps: true, chunk_length_s: 30, stride_length_s: 5 };\n    if (L.model !== 'english') { o.task = 'transcribe'; if (L.lang) o.language = L.lang; }   // English-only models take no language\n    var res = await loaded[M.id](audio.samples, o);\n    return segmentsFromChunks(res && res.chunks || [], audio.durMs);\n  }\n  var api = { LIB_URL: LIB_URL, MODELS: MODELS, LANGS: LANGS, chunkRanges: chunkRanges, segmentsFromChunks: segmentsFromChunks, splitLines: splitLines, recognize: recognize,\n    _reset: function () { loaded = {}; } };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api;\n  if (typeof window !== 'undefined') { window.NakiCaptions = api; window.NakiVersions = window.NakiVersions || {}; window.NakiVersions['captions.js'] = 'sound'; }\n  return api;\n})();\n","test":"'use strict';\n// node tests/sound.test.js\n// Sound effects (made by code, or your own files) and auto captions (speech stretches, speech recognition, placing the words on the edited timeline).\nconst assert = require('assert'), cp = require('child_process'), fs = require('fs'), os = require('os'), path = require('path');\nconst S = require('../www/sfx.js'), CA = require('../www/captions.js'), P = require('../www/project.js'), NP = require('../www/plan.js'), E = require('../www/export-engine.js'), C = require('../www/core.js');\nlet n = 0; const ok = (name, fn) => { fn(); n++; console.log('  ok  ' + name); };\nconst okAsync = []; const later = (name, fn) => okAsync.push([name, fn]);\n\n// ---------- sound effects made by code ----------\nok('effects: ten of them, each the right length, loud but not clipping, starting and ending in silence, and always the same', () => {\n  assert.strictEqual(S.LIST.length, 10);\n  S.LIST.forEach(x => {\n    const a = S.render(x.key, 48000), b = S.render(x.key, 48000); assert.strictEqual(a.length, Math.round(x.durMs * 48) , x.key + ' length');\n    let pk = 0; a.forEach(v => { pk = Math.max(pk, Math.abs(v)); }); assert(Math.abs(pk - 0.85) < 0.001, x.key + ' peak ' + pk);\n    assert(Math.abs(a[0]) < 0.01 && Math.abs(a[a.length - 1]) < 0.01, x.key + ' ends'); assert.deepStrictEqual(Array.from(a.slice(0, 500)), Array.from(b.slice(0, 500)), x.key + ' repeatable');\n    let e = 0; a.forEach(v => { e += v * v; }); assert(Math.sqrt(e / a.length) > 0.02, x.key + ' is not silent');\n  });\n  assert.strictEqual(S.render('nonsense'), null); assert.strictEqual(S.render('pop', 24000).length, Math.round(220 * 24), 'any sample rate');\n});\nok('effects: the WAV file has the right header and the same samples', () => {\n  const s = S.render('click', 48000), w = S.toWav(s, 48000), v = new DataView(w.buffer);\n  assert.strictEqual(String.fromCharCode(w[0], w[1], w[2], w[3]) + String.fromCharCode(w[8], w[9], w[10], w[11]), 'RIFFWAVE');\n  assert.strictEqual(w.length, 44 + s.length * 2); assert.strictEqual(v.getUint32(24, true), 48000); assert.strictEqual(v.getUint16(22, true), 1); assert.strictEqual(v.getUint16(34, true), 16); assert.strictEqual(v.getUint32(40, true), s.length * 2);\n  let peak = 0; for (let i = 0; i < s.length; i++) peak = Math.max(peak, Math.abs(v.getInt16(44 + i * 2, true))); assert(Math.abs(peak / 32767 - 0.85) < 0.002, 'peak ' + peak);\n});\n\n// ---------- the test project: a picture, a voice recording of 12 s ----------\nfunction make() {\n  return { naki: 'project', version: 1, fps: 30, durationMs: 12000, levels: [], assets: { movie: { type: 'video', durMs: 100000 }, voice: { type: 'audio', durMs: 12000 } },\n    tracks: [{ id: 't-movie', kind: 'video', role: 'movie', muted: false, hidden: false, volume: 1, locked: false, clips: [{ id: 'vA', type: 'video', asset: 'movie', start: 0, dur: 12000, in: 10000, speed: 1, volume: 1, fadeIn: 0, fadeOut: 0, link: 'lA' }] },\n      { id: 't-voice', kind: 'audio', role: 'voice', muted: false, hidden: false, volume: 1, locked: false, clips: [{ id: 'vo', type: 'audio', asset: 'voice', start: 0, dur: 12000, in: 0, speed: 1, volume: 1, fadeIn: 0, fadeOut: 0 }] }] };\n}\nconst base = make();\nconst clipsOf = (p, role) => p.tracks.filter(t => t.role === role).reduce((a, t) => a.concat(t.clips), []);\n\nok('sound effect: an audio clip at the playhead; overlapping ones get their own row; an empty row goes away; row ids stay unique', () => {\n  const o1 = {}, o2 = {}, o3 = {};\n  let p = P.addSfx(base, 1000, { name: 'Whoosh', durMs: 700 }, o1); assert.deepStrictEqual(P.validate(p), []);\n  const c = P.findClip(p, o1.id).clip, tr = P.findClip(p, o1.id).track;\n  assert.deepStrictEqual([c.type, c.start, c.dur, c.in, c.asset, c.volume, tr.kind, tr.role], ['audio', 1000, 700, 0, 'fx1', 1, 'audio', 'sfx']); assert.deepStrictEqual(p.assets.fx1, { type: 'audio', name: 'Whoosh', durMs: 700 });\n  p = P.addSfx(p, 1300, { name: 'Ding', durMs: 1500 }, o2); assert.strictEqual(p.tracks.filter(t => t.role === 'sfx').length, 2, 'overlapping in time: a second row');\n  p = P.addSfx(p, 5000, { name: 'Pop', durMs: 200 }, o3); assert.strictEqual(p.tracks.filter(t => t.role === 'sfx').length, 2, 'fits on the first row'); assert.strictEqual(p.assets.fx3.name, 'Pop');\n  const del = P.deleteClip(P.deleteClip(p, o3.id), o1.id); assert.strictEqual(del.tracks.filter(t => t.role === 'sfx').length, 1, 'the empty row is gone');\n  const ids = P.addSfx(del, 100, { name: 'x', durMs: 300 }, {}).tracks.map(t => t.id); assert.strictEqual(new Set(ids).size, ids.length, 'unique: ' + ids);\n  assert.strictEqual(P.addSfx(base, 11950, { name: 'x', durMs: 700 }, {}).tracks.find(t => t.role === 'sfx').clips[0].dur, 100, 'cut to what is left');\n  assert.strictEqual(P.sourceAt(p, 1500).audio.filter(a => a.role === 'sfx').length, 2, 'both sound at once');\n  const set = P.setClipProps(p, o1.id, { volume: 0.4, fadeOut: 300 }); assert.strictEqual(P.findClip(set, o1.id).clip.volume, 0.4, 'volume and fades work like any sound clip');\n  const sp = P.splitAt(p, 1300); assert.strictEqual(P.findClip(sp, o1.id) !== null && sp.tracks.find(t => t.role === 'sfx').clips.length >= 2, true);\n});\nok('plan: each effects row is its own sound lane, and each clip names its file', () => {\n  const o1 = {}, o2 = {}; let p = P.addSfx(base, 1000, { name: 'Whoosh', durMs: 700 }, o1); p = P.addSfx(p, 1300, { name: 'Ding', durMs: 1500 }, o2);\n  const a = NP.projectToPlan(p).audio.filter(x => x.file);\n  assert.deepStrictEqual(a.map(x => [x.src, x.file, x.startMs, x.durMs, x.inMs]), [['sfx1', 'fx1.in', 1000, 700, 0], ['sfx2', 'fx2.in', 1300, 1500, 0]]);\n  const m = P.setTrackProps(p, 't-fx1', { muted: true }); assert.deepStrictEqual(NP.projectToPlan(m).audio.filter(x => x.file).map(x => x.file), ['fx2.in'], 'a muted row is left out');\n  assert.strictEqual(NP.projectToPlan(base).audio.some(x => x.file), false);\n});\n\n// ---------- auto captions ----------\nok('captions: the stretches where you talked, found from the microphone history on the edited timeline', () => {\n  const lv = []; for (let i = 0; i < 200; i++) { const t = i * 50, talking = (t >= 500 && t < 3000) || (t >= 4000 && t < 4200) || (t >= 6000 && t < 9500); lv.push(C.dbToByte(talking ? -20 : -70)); }\n  const p = Object.assign(make(), { levels: lv, durationMs: 10000 });\n  assert.deepStrictEqual(P.speechRanges(p, { thresholdDb: -45 }).map(r => [r.start, r.end]), [[500, 3000], [6000, 9500]], 'the 0.2 s blip is too short; the first silence is not speech');\n  assert.deepStrictEqual(P.speechRanges(p, { thresholdDb: -45, minSpeechMs: 150 }).map(r => r.start), [500, 4000, 6000]);\n  assert.deepStrictEqual(P.speechRanges(Object.assign(make(), { levels: [] }), {}), []);\n  assert.deepStrictEqual(CA.chunkRanges([{ start: 0, end: 14000 }, { start: 15000, end: 16000 }], 6000), [{ start: 0, end: 4667 }, { start: 4667, end: 9333 }, { start: 9333, end: 14000 }, { start: 15000, end: 16000 }]);\n  const cut = P.rippleDelete(p, 3000, 6000); assert.deepStrictEqual(P.speechRanges(cut, { thresholdDb: -45 }).map(r => [r.start, r.end]), [[500, 6500]], 'after the pause is cut out, the two stretches of talking join into one');\n});\nok('captions: what the model returns is tidied (no end time, noises, tiny pieces) and long lines are broken at words', () => {\n  const segs = CA.segmentsFromChunks([{ timestamp: [0, 2.5], text: ' Hello there.' }, { timestamp: [2.5, 3], text: ' [BLANK_AUDIO]' }, { timestamp: [3, null], text: '  Second   part ' }, { timestamp: [null, 1], text: 'x' }, { timestamp: [7.9, 7.95], text: 'tiny' }], 9000);\n  assert.deepStrictEqual(segs, [{ startMs: 0, endMs: 2500, text: 'Hello there.' }, { startMs: 3000, endMs: 7900, text: 'Second part' }, { startMs: 7900, endMs: 8300, text: 'tiny' }]);\n  const lines = CA.splitLines([{ startMs: 0, endMs: 6000, text: 'one two three four five six seven eight nine ten' }], 20);\n  assert.deepStrictEqual(lines.map(l => l.text), ['one two three four', 'five six seven eight', 'nine ten']); assert.strictEqual(lines[0].startMs, 0); assert.strictEqual(lines[2].endMs, 6000);\n  lines.forEach((l, i) => { assert(l.endMs > l.startMs); if (i) assert.strictEqual(l.startMs, lines[i - 1].endMs, 'no gap or overlap'); });\n  assert.deepStrictEqual(CA.splitLines([{ startMs: 0, endMs: 1000, text: 'short' }], 40), [{ startMs: 0, endMs: 1000, text: 'short' }]);\n});\nok('captions: words found in the voice file land on the edited timeline, and only where that part of the voice is still used', () => {\n  const segs = [{ startMs: 1000, endMs: 3000, text: 'before the cut' }, { startMs: 4000, endMs: 5000, text: 'inside the cut' }, { startMs: 5500, endMs: 7500, text: 'across the end of the cut' }, { startMs: 9000, endMs: 11000, text: 'after' }];\n  assert.deepStrictEqual(P.captionsFromVoice(base, segs).map(c => [c.startMs, c.endMs]), [[1000, 3000], [4000, 5000], [5500, 7500], [9000, 11000]], 'untouched: same times');\n  const cut = P.rippleDelete(base, 3500, 6000), it = P.captionsFromVoice(cut, segs);\n  assert.deepStrictEqual(it.map(c => [c.startMs, c.endMs, c.text]), [[1000, 3000, 'before the cut'], [3500, 5000, 'across the end of the cut'], [6500, 8500, 'after']], 'the cut part is gone, the rest moves earlier');\n  const moved = JSON.parse(JSON.stringify(base)); moved.tracks[1].clips[0].start = 500; moved.tracks[1].clips[0].in = 0; assert.strictEqual(P.captionsFromVoice(moved, [{ startMs: 1000, endMs: 2000, text: 'x' }])[0].startMs, 1500, 'a voice moved later moves its captions');\n  const trimmed = JSON.parse(JSON.stringify(base)); Object.assign(trimmed.tracks[1].clips[0], { in: 2000, dur: 4000 }); assert.deepStrictEqual(P.captionsFromVoice(trimmed, [{ startMs: 1000, endMs: 3000, text: 'x' }]).map(c => [c.startMs, c.endMs]), [[0, 1000]], 'only the part still used');\n  const out = {}, withCaps = P.addCaptions(cut, it, { replace: true }, out); assert.strictEqual(out.added, 3); assert.deepStrictEqual(P.captionList(withCaps).map(c => c.text), ['before the cut', 'across the end of the cut', 'after']);\n});\nlater('captions: recognize() reads the voice, loads the right model once, asks for timestamps, and passes the language only to models that take one', async () => {\n  CA._reset(); const calls = [], created = [];\n  const lib = { pipeline: async (task, id, o) => { created.push([task, id]); o.progress_callback({ status: 'progress', progress: 42.4, file: 'm.onnx' }); return async (samples, opts) => { calls.push([samples.length, opts]); return { text: 'hi', chunks: [{ timestamp: [0.5, 2], text: ' Hello' }, { timestamp: [2, null], text: ' world' }] }; }; } };\n  const decode = async (b) => ({ samples: new Float32Array(1600), durMs: 4000 }), msgs = [];\n  let segs = await CA.recognize({}, { language: 'english', lib, decode, onStatus: m => msgs.push(m) });\n  assert.deepStrictEqual(created[0], ['automatic-speech-recognition', 'onnx-community/whisper-tiny.en']); assert.deepStrictEqual(calls[0], [1600, { return_timestamps: true, chunk_length_s: 30, stride_length_s: 5 }], 'English-only model: no language, no task');\n  assert.deepStrictEqual(segs, [{ startMs: 500, endMs: 2000, text: 'Hello' }, { startMs: 2000, endMs: 4000, text: 'world' }]);\n  assert(msgs.some(m => /Downloading the speech model\\.\\.\\. 42%/.test(m)) && /Reading/.test(msgs[0]) && /Listening/.test(msgs[msgs.length - 1]), msgs.join(' | '));\n  segs = await CA.recognize({}, { language: 'english', lib, decode }); assert.strictEqual(created.length, 1, 'the model is loaded once');\n  await CA.recognize({}, { language: 'swahili', lib, decode }); assert.strictEqual(created[1][1], 'onnx-community/whisper-base'); assert.deepStrictEqual(calls[2][1], { return_timestamps: true, chunk_length_s: 30, stride_length_s: 5, task: 'transcribe', language: 'swahili' });\n  await CA.recognize({}, { language: 'auto', lib, decode }); assert.strictEqual('language' in calls[3][1], false, 'detect the language');\n  CA._reset(); assert.deepStrictEqual(await CA.recognize({}, { lib: { pipeline: async () => async () => ({ chunks: [] }) }, decode, language: 'auto' }), [], 'nothing heard: no lines');\n});\n\n// ---------- the ffmpeg engine ----------\nconst info0 = { hasAudio: false, audioMono: false, width: 640, height: 360, sar: 1, durationSec: 6 };\nconst plan0 = (audio) => ({ naki: 'export-plan', version: 2, durationMs: 4000, movie: { durationMs: 6000 }, video: [{ type: 'black', sessionStart: 0, sessionEnd: 4000 }], audio: audio });\nconst sfx = (src, file, startMs, durMs, extra) => Object.assign({ src, file, startMs, durMs, inMs: 0, points: [[0, 1]] }, extra || {});\nok('ffmpeg engine: each effects lane is cut from its own file, and the lanes are mixed with the rest', () => {\n  const r = E.planToJobs(plan0([sfx('sfx1', 'fx1.in', 500, 1000), sfx('sfx2', 'fx2.in', 800, 1500)]), info0, { height: 360 });\n  assert.deepStrictEqual(Object.keys(r.lanes).sort(), ['sfx1', 'sfx2']);\n  const a = r.jobs.find(j => /sound sfx1/.test(j.label)).args, b = r.jobs.find(j => /sound sfx2/.test(j.label)).args;\n  assert(a.join(' ').includes('-i fx1.in') && b.join(' ').includes('-i fx2.in'), a.join(' '));\n  const tails = r.jobs.filter(j => /^t_sfx/.test(j.produces)).map(j => j.produces).sort(); assert.deepStrictEqual(tails, ['t_sfx1.wav', 't_sfx2.wav'], 'every lane has its own tail file');\n  const mix = E.finalMixArgs(Object.keys(r.lanes), 4000).join(' '); assert(mix.includes('lane_sfx1.txt') && mix.includes('lane_sfx2.txt') && mix.includes('amix=inputs=2'));\n  const none = E.planToJobs(plan0([]), info0, { height: 360 }); assert.deepStrictEqual(Object.keys(none.lanes), []);\n});\n// ---- real ffmpeg, only when this computer has a recent one ----\nfunction ffmpegOk() { const r = cp.spawnSync('ffmpeg', ['-version'], { encoding: 'utf8' }); const m = r.status === 0 && /version\\s+n?(\\d+)/.exec(r.stdout); return !!m && +m[1] >= 5; }\nif (ffmpegOk()) {\n  const renderAudio = (audio, files) => {\n    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'naki-sfx-')), sh = (a) => cp.spawnSync('ffmpeg', ['-y', '-v', 'error'].concat(a), { cwd: dir, encoding: 'utf8' });\n    Object.keys(files).forEach(f => fs.writeFileSync(path.join(dir, f), Buffer.from(S.toWav(S.render(files[f], 48000), 48000))));\n    const built = E.planToJobs(plan0(audio), info0, { height: 360 });\n    built.jobs.forEach(j => { if (j.files) Object.keys(j.files).forEach(f => fs.writeFileSync(path.join(dir, f), Buffer.from(j.files[f]))); const x = sh(j.args); assert.strictEqual(x.status, 0, j.label + ': ' + x.stderr); });\n    fs.writeFileSync(path.join(dir, 'video.txt'), built.videoList.map(f => \"file '\" + f + \"'\\n\").join(''));\n    Object.keys(built.lanes).forEach(l => fs.writeFileSync(path.join(dir, 'lane_' + l + '.txt'), built.lanes[l].map(f => \"file '\" + f + \"'\\n\").join('')));\n    let r = sh(E.finalMixArgs(Object.keys(built.lanes), 4000)); assert.strictEqual(r.status, 0, r.stderr);\n    const o = cp.spawnSync('ffmpeg', ['-v', 'error', '-i', path.join(dir, 'out.mp4'), '-vn', '-ac', '1', '-ar', '8000', '-f', 's16le', '-'], { encoding: null });\n    const pcm = new Int16Array(o.stdout.buffer, o.stdout.byteOffset, Math.floor(o.stdout.length / 2));\n    const rms = (a, b) => { let s = 0, c = 0; for (let i = Math.floor(a * 8000); i < Math.min(pcm.length, Math.floor(b * 8000)); i++) { s += pcm[i] * pcm[i]; c++; } return Math.sqrt(s / Math.max(1, c)) / 32768; };\n    const dur = +cp.spawnSync('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', path.join(dir, 'out.mp4')], { encoding: 'utf8' }).stdout.trim();\n    return { rms, dur, done: () => fs.rmSync(dir, { recursive: true, force: true }) };\n  };\n  ok('real ffmpeg: an effect sounds where it was put, and nowhere else; two at once are louder than one', () => {\n    let r = renderAudio([sfx('sfx1', 'fx1.in', 1000, 1500)], { 'fx1.in': 'ding' });\n    try { assert(Math.abs(r.dur - 4) < 0.1, 'length ' + r.dur); assert(r.rms(0, 0.9) < 0.002 && r.rms(2.7, 3.9) < 0.002, 'silent outside: ' + r.rms(0, 0.9) + ' ' + r.rms(2.7, 3.9)); assert(r.rms(1.0, 1.4) > 0.05, 'sounds inside: ' + r.rms(1.0, 1.4)); } finally { r.done(); }\n    const one = renderAudio([sfx('sfx1', 'fx1.in', 1000, 1500)], { 'fx1.in': 'ding' }), two = renderAudio([sfx('sfx1', 'fx1.in', 1000, 1500), sfx('sfx2', 'fx2.in', 1000, 900)], { 'fx1.in': 'ding', 'fx2.in': 'drop' });\n    try { assert(two.rms(1.0, 1.5) > one.rms(1.0, 1.5) * 1.1, 'together: ' + two.rms(1.0, 1.5) + ' vs ' + one.rms(1.0, 1.5)); assert(Math.abs(two.dur - 4) < 0.1); } finally { one.done(); two.done(); }\n  });\n  ok('real ffmpeg: volume and where in the file to start both work, and one effect can follow another on the same row', () => {\n    const loud = renderAudio([sfx('sfx1', 'fx1.in', 500, 600)], { 'fx1.in': 'whoosh' }), quiet = renderAudio([sfx('sfx1', 'fx1.in', 500, 600, { points: [[0, 0.25]] })], { 'fx1.in': 'whoosh' });\n    try { const a = loud.rms(0.6, 1.0), b = quiet.rms(0.6, 1.0); assert(b < a * 0.4 && b > a * 0.1, 'a quarter of the volume: ' + a + ' -> ' + b); } finally { loud.done(); quiet.done(); }\n    const seq = renderAudio([sfx('sfx1', 'fx1.in', 300, 400), sfx('sfx1', 'fx1.in', 2000, 400, { inMs: 200 })], { 'fx1.in': 'ding' });\n    try { assert(seq.rms(0.35, 0.65) > 0.05 && seq.rms(2.05, 2.35) > 0.02 && seq.rms(1.0, 1.8) < 0.002, 'two on one row: ' + seq.rms(0.35, 0.65) + ' ' + seq.rms(2.05, 2.35) + ' ' + seq.rms(1.0, 1.8)); } finally { seq.done(); }\n  });\n} else console.log('  --  real-file checks skipped (need ffmpeg 5 or newer on this computer)');\n(async () => { for (const [name, fn] of okAsync) { await fn(); n++; console.log('  ok  ' + name); } console.log('\\n' + n + ' checks passed'); })().catch(e => { console.error(e); process.exit(1); });\n","projectSound":"// ---------- sound effects ----------\n// A sound effect is an ordinary audio clip on an \"Effects\" row (role 'sfx'). The sound itself is a file kept by the page (project.assets only knows its name\n// and length), so it splits, trims, moves, fades and changes volume like any other sound clip. Effects that overlap in time go on separate rows.\n// info = { name, durMs }.\nfunction addSfx(p, t, info, out){\n  info = info || {};\n  var total = p.durationMs; if (!(total > 0)) return p;\n  var start = Math.max(0, Math.min(Math.round(t), total - 100)), d = Math.min(Math.max(100, Math.round(info.durMs || 1000)), total - start); if (d < 100) return p;\n  var q = cloneProject(p), n = 1; while (q.assets['fx' + n]) n++;\n  var asset = 'fx' + n; q.assets[asset] = { type: 'audio', name: info.name || 'effect', durMs: info.durMs || null };\n  var rows = q.tracks.filter(function (x){ return x.role === 'sfx'; }), tr = null;\n  for (var i = 0; i < rows.length && !tr; i++) if (!rows[i].clips.some(function (c){ return start < clipEnd(c) && start + d > c.start; })) tr = rows[i];\n  if (!tr){\n    var k = 1; while (q.tracks.some(function (x){ return x.id === 't-fx' + k; })) k++;\n    tr = { id: 't-fx' + k, kind: 'audio', role: 'sfx', muted: false, hidden: false, volume: 1, locked: false, clips: [] }; q.tracks.push(tr);\n  }\n  var clip = { id: newId('c'), type: 'audio', asset: asset, start: start, dur: d, in: 0, speed: 1, volume: 1, fadeIn: 0, fadeOut: 0 };\n  tr.clips.push(clip); if (out){ out.id = clip.id; out.asset = asset; }\n  return finish(q);\n}\n\n// ---------- auto captions ----------\n// The stretches where you were talking, on the edited timeline: the quiet pauses (findSilentRanges) turned inside out. The microphone history is cut\n// along with the video, so this stays right after edits.\nfunction speechRanges(p, o){\n  o = Object.assign({ thresholdDb: -42, minPauseMs: 500, minSpeechMs: 300 }, o || {});\n  var lv = p.levels || [], sil = findSilentRanges(lv, { thresholdDb: o.thresholdDb, minMs: o.minPauseMs, padMs: 0 }), out = [], cur = 0;\n  sil.forEach(function (r){ if (r.start - cur >= o.minSpeechMs) out.push({ start: cur, end: r.start }); cur = r.end; });\n  var end = Math.min(p.durationMs, lv.length * _C.LEVEL_STEP_MS); if (end - cur >= o.minSpeechMs) out.push({ start: cur, end: end });\n  return out;\n}\n// Words found in the voice FILE (segs = [{ startMs, endMs, text }], times in the file) placed on the edited timeline, wherever that part of the voice is still\n// used. A line that falls in a part that was cut out is dropped; one that crosses a cut is kept in each piece.\nfunction captionsFromVoice(p, segs){\n  var voice = []; p.tracks.forEach(function (t){ if (t.role === 'voice') t.clips.forEach(function (c){ voice.push(c); }); });\n  var out = [];\n  (segs || []).forEach(function (sg){\n    voice.forEach(function (c){\n      var sp = c.speed || 1, s = Math.max(sg.startMs, c.in), e = Math.min(sg.endMs, c.in + c.dur * sp);\n      if (e - s < 150) return;\n      out.push({ startMs: Math.round(c.start + (s - c.in) / sp), endMs: Math.round(c.start + (e - c.in) / sp), text: sg.text });\n    });\n  });\n  return out.sort(function (a, b){ return a.startMs - b.startMs; });\n}\n\n","editorFns":"  // ----- sound effects -----\n  function placeSfx(info){\n    var out = {}, q = P.addSfx(E.hist.cur, Math.round(E.t), info, out);\n    if (q === E.hist.cur){ toast('There is no room for a sound effect at the playhead.'); return; }\n    E.hooks.setSfxFile(out.asset, info.file);\n    E.sel = out.id; commit(q); closePanel(); toast('Added at the playhead. Press play to hear it.');\n  }\n  function addSfxBuiltin(key){\n    if (!NSFX || !E.hooks.setSfxFile){ toast('Sound effects are not available here.'); return; }\n    var def = NSFX.find(key), wav = NSFX.toWav(NSFX.render(key, 48000), 48000);\n    placeSfx({ file: new File([wav], key + '.wav', { type: 'audio/wav' }), name: def.label, durMs: def.durMs });\n  }\n  function addSfxFromFile(){\n    if (!E.hooks.pickSfx || !E.hooks.setSfxFile){ toast('Importing sounds is not available here.'); return; }\n    pause();\n    Promise.resolve(E.hooks.pickSfx()).then(function (info){ if (info) placeSfx(info); });\n  }\n  // The effects that sound at the playhead: one small audio element each, kept in step with the playhead.\n  function syncSfx(s){\n    if (!E.sfxEls) E.sfxEls = {};\n    var want = {};\n    s.audio.forEach(function (a){\n      if (a.role !== 'sfx') return;\n      var c = a.clip, url = E.hooks.sfxUrl ? E.hooks.sfxUrl(c.asset) : ''; if (!url) return;\n      want[c.id] = true;\n      var d = E.sfxEls[c.id]; if (!d){ d = E.sfxEls[c.id] = new Audio(); d.preload = 'auto'; d._src = ''; }\n      if (d._src !== url){ d._src = url; d.src = url; }\n      d.volume = Math.max(0, Math.min(1, a.gain));\n      var at = a.sourceMs / 1000;\n      if (E.playing){\n        if (d.paused){ d.currentTime = at; var pr = d.play(); if (pr && pr.catch) pr.catch(function (){}); }\n        else if (Math.abs(d.currentTime - at) > 0.3) d.currentTime = at;\n      } else if (!d.paused) d.pause();\n    });\n    Object.keys(E.sfxEls).forEach(function (id){ if (!want[id]){ try { E.sfxEls[id].pause(); } catch (e) {} delete E.sfxEls[id]; } });\n  }\n  function pauseSfx(){ Object.keys(E.sfxEls || {}).forEach(function (id){ try { E.sfxEls[id].pause(); } catch (e) {} }); }\n  function removeSfx(){ pauseSfx(); E.sfxEls = {}; }\n  // ----- auto captions -----\n  function applyCaptionItems(items){\n    var had = P.captionList(E.hist.cur).length;\n    if (had && !confirm('Replace your ' + had + ' caption lines with the ' + items.length + ' new ones?')){ renderDock(); return; }\n    var out = {}, q = P.addCaptions(E.hist.cur, items, { replace: true }, out);\n    if (q === E.hist.cur && !out.added){ toast('None of the lines fit the video.'); renderDock(); return; }\n    commit(q); openPanel('captions', 'text');\n    toast(out.added + ' caption line' + (out.added === 1 ? '' : 's') + ' added. Check them, speech recognition makes mistakes.', 8000);\n  }\n  // Works for any language: a caption slot for every stretch where you were talking. You type the words.\n  function markSpeech(){\n    var ranges = NCAP.chunkRanges(P.speechRanges(E.hist.cur, { thresholdDb: E.quietDb }), 6000);\n    if (!ranges.length){ toast('No speech was found in your recording.'); return; }\n    applyCaptionItems(ranges.map(function (r){ return { startMs: r.start, endMs: r.end, text: '\\u2026' }; }));\n  }\n  function runAutoCaptions(langKey){\n    if (E.ac && E.ac.running) return;\n    var blob = E.hooks.getVoiceBlob && E.hooks.getVoiceBlob();\n    if (!blob || !blob.size){ toast('There is no voice recording to listen to.'); return; }\n    pause(); E.ac = { running: true, msg: 'Starting...' }; renderDock();\n    var status = function (m){ if (E.ac) E.ac.msg = m; if (E.acStatus) E.acStatus.textContent = m; };\n    NCAP.recognize(blob, { language: langKey, onStatus: status }).then(function (segs){\n      var items = P.captionsFromVoice(E.hist.cur, NCAP.splitLines(segs, 42));\n      E.ac = null;\n      if (!items.length){ toast('No speech was found in the part of the recording you kept.', 7000); renderDock(); return; }\n      applyCaptionItems(items);\n    }).catch(function (err){\n      E.ac = null; console.error('auto captions failed', err); renderDock();\n      toast('Auto captions did not work' + (err && err.message ? ': ' + err.message : '') + '. The first time it needs internet.', 10000);\n    });\n  }\n","editorPanels":"    sfxpick: { title: 'Sound effects', build: function (body){\n      var g = mk('div', 'ed-chips wrap');\n      (NSFX ? NSFX.LIST : []).forEach(function (x){ var b = btn(null, x.label, 'ed-chip'); b.onclick = function (){ addSfxBuiltin(x.key); }; g.appendChild(b); });\n      body.appendChild(g);\n      body.appendChild(actions([{ id: 'edSfxImport', label: 'Import your own sound', run: addSfxFromFile }]));\n      body.appendChild(mk('div', 'ed-hint', 'Tap one to put it at the playhead. Drag it on the timeline to move it; under Clip you can change its volume and fades.'));\n    } },\n    autocaptions: { title: 'Auto captions', build: function (body){\n      var keys = NCAP.LANGS.map(function (l){ return { key: l.key, label: l.label }; }), cur = chipKey('autocaptions', keys, 'english'), run = !!(E.ac && E.ac.running);\n      body.appendChild(chips(keys, cur, pickChip('autocaptions')));\n      var st = mk('div', 'ed-hint', run ? E.ac.msg : 'Listens to your recording on this device and writes the captions at the right times. English works best. Luganda is not supported, so for Luganda use Mark speech and type the words.');\n      E.acStatus = st; body.appendChild(st);\n      body.appendChild(actions([{ id: 'edAutoCapStart', label: run ? 'Working...' : 'Start', run: function (){ runAutoCaptions(cur); } }]));\n    } },\n","css":"\n/* sound effects, auto captions */\n.ed-chips.wrap{flex-wrap:wrap;overflow:visible}\n.ed-clip.k-sfx{background:#b5792a;border-color:#e0a24a}\n","indexFns":"// ---------- sound effects: the sound files behind the effect clips (kept on this device with the session) ----------\nS.sfx = {};\nfunction sfxUrl(id){ var o = S.sfx[id]; return o ? o.url : ''; }\nfunction setSfxFile(id, file){\n  var old = S.sfx[id]; if (old && old.url) URL.revokeObjectURL(old.url);\n  S.sfx[id] = { file: file, url: URL.createObjectURL(file) };\n  if (DB.ok && S.sess) DB.put('sfx', { sid: S.sess.id, n: +String(id).replace('fx', ''), id: id, name: file.name, blob: file }).catch(function(){\n    toast('This sound is too large to remember on this device. You will need to add it again next time.', 8000);\n  });\n}\nfunction loadSfx(s){\n  Object.keys(S.sfx).forEach(function(k){ try { if (S.sfx[k].url) URL.revokeObjectURL(S.sfx[k].url); } catch (e) {} });\n  S.sfx = {};\n  if (!DB.ok) return;\n  DB.range('sfx', s.id).then(function(list){\n    list.forEach(function(r){\n      if (!r || !r.blob) return;\n      var f = new File([r.blob], r.name || r.id, { type: r.blob.type });\n      S.sfx[r.id] = { file: f, url: URL.createObjectURL(f) };\n    });\n  }, function(){});\n}\nfunction pickSfx(){\n  return new Promise(function(resolve){\n    var inp = $('sfxPick'); inp.value = '';\n    inp.onchange = function(){\n      var f = inp.files && inp.files[0]; if (!f) return resolve(null);\n      var a = new Audio(), u = URL.createObjectURL(f); a.preload = 'metadata';\n      a.onloadedmetadata = function(){ URL.revokeObjectURL(u); resolve({ file: f, name: f.name, durMs: isFinite(a.duration) ? Math.round(a.duration * 1000) : 3000 }); };\n      a.onerror = function(){ URL.revokeObjectURL(u); toast('This sound file could not be read. Try an MP3, M4A or WAV.'); resolve(null); };\n      a.src = u;\n    };\n    inp.click();\n  });\n}\nfunction getVoiceBlob(){ return S.sess ? S.sess.voiceBlob : null; }\n\n","indexExport":"\n  // The sound files behind the effects. An effect whose file is missing is left out, and you are told.\n  var sfxFiles = {}, lostFx = false;\n  plan.audio = (plan.audio || []).filter(function(a){\n    if (!a.file) return true;\n    var f = S.sfx[a.file.replace(/\\.in$/, '')];\n    if (f && f.file){ sfxFiles[a.file] = f.file; return true; }\n    lostFx = true; return false;\n  });\n  if (lostFx) toast('A sound effect file is missing, so it was left out.', 9000);\n  ffmpegOpts.sfxFiles = webcodecsOpts.sfxFiles = sfxFiles;\n"};

function load(rel){ const f = path.join(root, rel); const raw = fs.readFileSync(f, 'utf8'); return { f, crlf: raw.includes('\r\n'), text: raw.replace(/\r\n/g, '\n') }; }
function save(o){ fs.writeFileSync(o.f, o.crlf ? o.text.replace(/\n/g, '\r\n') : o.text); }
const problems = [];
const nm = (o) => path.basename(o.f);
function rep(o, find, replace, label, times){
  const n = o.text.split(find).length - 1;
  if (n !== (times || 1)){ problems.push(label + ': found ' + n + ' times (need exactly ' + (times || 1) + ') in ' + nm(o)); return; }
  o.text = o.text.split(find).join(replace);
}
function repRe(o, re, replace, label){
  const m = o.text.match(new RegExp(re.source, 'g'));
  if (!m || m.length !== 1){ problems.push(label + ': found ' + (m ? m.length : 0) + ' times (need exactly 1) in ' + nm(o)); return; }
  o.text = o.text.replace(re, function (m, g1){ return replace.replace('$1', g1 === undefined ? '' : g1); });
}

const pj = load('www/project.js'), pl = load('www/plan.js'), ee = load('www/export-engine.js'), wc = load('www/webcodecs-export.js'),
  ed = load('www/editor.js'), css = load('www/editor.css'), ix = load('www/index.html'), sw = load('www/sw.js'), pk = load('package.json');
if (fs.existsSync(path.join(root, 'www', 'sfx.js'))){ console.log('Already applied (www/sfx.js exists). Nothing to do.'); process.exit(0); }

// ---- project.js ----
rep(pj, '// ---------- undo / redo ----------', B.projectSound + '// ---------- undo / redo ----------', 'project: undo marker');
rep(pj, "return (t.kind !== 'sticker' && t.kind !== 'overlay') || t.clips.length; }", "return (t.kind !== 'sticker' && t.kind !== 'overlay' && t.role !== 'sfx') || t.clips.length; }", 'project: empty effects rows go away');
rep(pj, 'overlaysAt: overlaysAt };', 'overlaysAt: overlaysAt,\n  addSfx: addSfx, speechRanges: speechRanges, captionsFromVoice: captionsFromVoice };', 'project: api list');
repRe(pj, /NakiVersions\['project\.js'\] = '[^']*'/, "NakiVersions['project.js'] = 'sound'", 'project: version');

// ---- plan.js ----
rep(pl, 'var src = ROLE_SRC[tr.role]; if (!src) return;', "var src = ROLE_SRC[tr.role] || (tr.role === 'sfx' ? 'sfx' + String(tr.id).replace(/\\D/g, '') : null); if (!src) return;   // each effects row is its own lane", 'plan: effects lanes');
rep(pl, "if (src === 'movie' && c.reverse) a.reverse = true;", "if (src === 'movie' && c.reverse) a.reverse = true;\n        if (tr.role === 'sfx') a.file = c.asset + '.in';", 'plan: effects file name');
repRe(pl, /NakiVersions\['plan\.js'\] = '[^']*'/, "NakiVersions['plan.js'] = 'sound'", 'plan: version');

// ---- export-engine.js (ffmpeg) ----
rep(ee, 'var lanes = { movie: [], voice: [], music: [] }, cursor = { movie: 0, voice: 0, music: 0 };',
  "var lanes = { movie: [], voice: [], music: [] }, cursor = { movie: 0, voice: 0, music: 0 };\n  (plan.audio || []).forEach(function (c) { if (c.file && /^sfx/.test(c.src) && !lanes[c.src]) { lanes[c.src] = []; cursor[c.src] = 0; } });   // one lane for each effects row", 'ffmpeg: effects lanes');
rep(ee, "'-i', SRC_FILE[src]]", "'-i', c.file || SRC_FILE[src]]", 'ffmpeg: each effect from its own file', 2);
rep(ee, "var tail = 't' + src[0] + '.wav';", "var tail = 't' + (/^sfx/.test(src) ? '_' + src : src[0]) + '.wav';", 'ffmpeg: tail file names');
rep(ee, "extra.push(ovIds[oi] + '.in'); }",
  "extra.push(ovIds[oi] + '.in'); }\n    var sfxNames = Object.keys(opts.sfxFiles || {});\n    for (var si = 0; si < sfxNames.length; si++) { say('Loading your sound effects...'); ffmpeg.writeFile(sfxNames[si], await fetchFile(opts.sfxFiles[sfxNames[si]])); extra.push(sfxNames[si]); }", 'ffmpeg: effects files');

// ---- webcodecs-export.js (fast engine) ----
rep(wc, 'var totalSamples = Math.round(plan.durationMs / 1000 * AUDIO_SR);',
  "var sfxBufs = {}, sfxNames = Object.keys(sources.sfxFiles || {});   // the sound effects, decoded once\n    for (var si = 0; si < sfxNames.length; si++) { try { sfxBufs[sfxNames[si]] = await decodeWhole(sources.sfxFiles[sfxNames[si]]); } catch (e) {} }\n    var totalSamples = Math.round(plan.durationMs / 1000 * AUDIO_SR);", 'fast: decode the effects');
rep(wc, "if (c.src === 'voice' || c.src === 'music') {",
  "if (c.file) {   // a sound effect: its own file\n          var fbuf = sfxBufs[c.file];\n          if (!fbuf || inStartSec >= fbuf.duration) continue;\n          var fsrc = ctx.createBufferSource();\n          fsrc.buffer = fbuf; fsrc.connect(gainNode);\n          fsrc.start((oStart - winStartMs) / 1000, inStartSec, Math.min(spanSec, fbuf.duration - inStartSec));\n        } else if (c.src === 'voice' || c.src === 'music') {", 'fast: play the effects');
rep(wc, 'await renderAudio(M, plan, { movieAudioTrack: audioTrack, voiceBlob: voiceBlob, musicFile: opts.musicFile }, audioSource, prog);',
  'await renderAudio(M, plan, { movieAudioTrack: audioTrack, voiceBlob: voiceBlob, musicFile: opts.musicFile, sfxFiles: opts.sfxFiles }, audioSource, prog);', 'fast: pass the effects');

// ---- index.html ----
rep(ix, '<script src="anim.js"></script>', '<script src="anim.js"></script>\n<script src="sfx.js"></script>\n<script src="captions.js"></script>', 'page: scripts');
rep(ix, "var r = indexedDB.open('naki', 5);", "var r = indexedDB.open('naki', 6);", 'page: database version');
rep(ix, "if (!d.objectStoreNames.contains('overlays')) d.createObjectStore('overlays', { keyPath: ['sid', 'n'] });",
  "if (!d.objectStoreNames.contains('overlays')) d.createObjectStore('overlays', { keyPath: ['sid', 'n'] });\n        if (!d.objectStoreNames.contains('sfx')) d.createObjectStore('sfx', { keyPath: ['sid', 'n'] });", 'page: effects store');
rep(ix, "self.delRange('overlays', sid),", "self.delRange('overlays', sid),\n      self.delRange('sfx', sid),", 'page: deleting a session deletes its effects');
rep(ix, '<input type="file" id="overlayPick" accept="image/*,video/*,.mp4,.mov,.webm" hidden>', '<input type="file" id="overlayPick" accept="image/*,video/*,.mp4,.mov,.webm" hidden>\n<input type="file" id="sfxPick" accept="audio/*,.mp3,.m4a,.wav,.ogg,.aac" hidden>', 'page: effects picker');
rep(ix, 'function loadEdits(s){', B.indexFns + 'function loadEdits(s){', 'page: effects functions');
rep(ix, 'loadOverlays(s);', 'loadOverlays(s);\n  loadSfx(s);', 'page: load effects with the session');
rep(ix, 'overlayUrl: overlayUrl, pickOverlay: pickOverlay, setOverlayFile: setOverlayFile,', 'overlayUrl: overlayUrl, pickOverlay: pickOverlay, setOverlayFile: setOverlayFile,\n  sfxUrl: sfxUrl, pickSfx: pickSfx, setSfxFile: setSfxFile, getVoiceBlob: getVoiceBlob,', 'page: editor hooks');
rep(ix, 'ffmpegOpts.overlayFiles = webcodecsOpts.overlayFiles = ovFiles;', 'ffmpegOpts.overlayFiles = webcodecsOpts.overlayFiles = ovFiles;' + B.indexExport, 'page: effects files for the export');
repRe(ix, /var want = \{[^}]*\};/, "var want = { 'editor.js': 'sound', 'project.js': 'sound', 'plan.js': 'sound', 'anim.js': 'overlay-kf', 'sfx.js': 'sound', 'captions.js': 'sound', 'format.js': 'format-bg', 'stickers.js': 'effects', 'presets.js': 'effects', 'look.js': 'titles-more-adjust', 'reverse.js': 'reverse' };", 'page: version list');

// ---- sw.js and package.json ----
rep(sw, "'./anim.js', ", "'./anim.js', './sfx.js', './captions.js', ", 'service worker: file list');
repRe(pk, /("test":\s*"[^"]*)"/, '$1 && node tests/sound.test.js"', 'package.json: test list');

// ---- editor.js ----
const NANIMLINE = "var NANIM = (typeof module !== 'undefined' && module.exports) ? require('./anim.js') : (typeof window !== 'undefined' ? window.NakiAnim : null);";
rep(ed, NANIMLINE, NANIMLINE + "\n  var NSFX = (typeof module !== 'undefined' && module.exports) ? require('./sfx.js') : (typeof window !== 'undefined' ? window.NakiSfx : null);\n  var NCAP = (typeof module !== 'undefined' && module.exports) ? require('./captions.js') : (typeof window !== 'undefined' ? window.NakiCaptions : null);", 'editor: libraries');
rep(ed, "overlay: 'Overlay' };", "overlay: 'Overlay', sfx: 'Effects' };", 'editor: row name');
rep(ed, ": (ROLE_NAME[tr.role] || 'Audio');", ": tr.role === 'sfx' ? 'Effect \\u00b7 ' + ((E.proj.assets[c.asset] && E.proj.assets[c.asset].name) || '') : (ROLE_NAME[tr.role] || 'Audio');", 'editor: effect clip name');
rep(ed, "items.push({ id: 'edMix', label: 'Volume', icon: G.mix, run: function (){ openPanel('mix'); } });",
  "items.push({ id: 'edSfx', label: 'Effects', icon: G.music, run: function (){ openPanel('sfxpick'); } });\n      items.push({ id: 'edMix', label: 'Volume', icon: G.mix, run: function (){ openPanel('mix'); } });", 'editor: Effects button');
rep(ed, "{ id: 'edCapExport', label: 'Save .srt', run: exportSrtFile }]));",
  "{ id: 'edCapExport', label: 'Save .srt', run: exportSrtFile }]));\n      body.appendChild(actions([{ id: 'edCapAuto', label: 'Auto captions', run: function (){ openPanel('autocaptions'); } }, { id: 'edCapMark', label: 'Mark speech', run: markSpeech }]));", 'editor: captions panel');
rep(ed, 'function layoutTextLayer(){ layoutTextLayerBase(); layoutPicture(); syncStickers(); syncOverlays(); }', B.editorFns.replace(/^  /, '') + '  function layoutTextLayer(){ layoutTextLayerBase(); layoutPicture(); syncStickers(); syncOverlays(); }', 'editor: functions');
rep(ed, 'syncStickers(); syncOverlays(); syncTransition(m, s, vc);', 'syncStickers(); syncOverlays(); syncSfx(s); syncTransition(m, s, vc);', 'editor: sync');
rep(ed, 'E.ui.xvid.pause(); pauseOverlays(); }', 'E.ui.xvid.pause(); pauseOverlays(); pauseSfx(); }', 'editor: pause');
rep(ed, 'removeOverlays();', 'removeOverlays(); removeSfx();', 'editor: close');
rep(ed, "    texts: { title: 'Your texts', build: function (body){", B.editorPanels + "    texts: { title: 'Your texts', build: function (body){", 'editor: panels');
repRe(ed, /NakiVersions\['editor\.js'\] = '[^']*'/, "NakiVersions['editor.js'] = 'sound'", 'editor: version');
css.text = css.text.replace(/\s*$/, '\n') + B.css;

if (problems.length){
  console.log('NOTHING WAS CHANGED. These spots did not match your files:\n  - ' + problems.join('\n  - '));
  console.log('\nSend me that list (and the file names) and I will adjust.');
  process.exit(1);
}
[pj, pl, ee, wc, ed, css, ix, sw, pk].forEach(save);
fs.writeFileSync(path.join(root, 'www', 'sfx.js'), B.sfxJs);
fs.writeFileSync(path.join(root, 'www', 'captions.js'), B.captionsJs);
fs.writeFileSync(path.join(root, 'tests', 'sound.test.js'), B.test);
console.log('Done. Changed 9 files, added www/sfx.js, www/captions.js and tests/sound.test.js.\nNow run:  npm test');